INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('nature', 'khinae', 'khinae', 'Descendant de Khinae', 'L''espèce avant tout : une Lignée, sa Variante, un Sang vif partagé avec les Garous.', '{"nature":"khinae","description":"Les descendants non lupins de Khinae regroupent des lignées prédatrices très différentes : canidés errants, renards, félins, rapaces, requins, serpents, Boudas, Berserkirs ou crocodiliens. Leur héritage rejoint normalement le Cycle et autorise transformation, régénération et forme hybride, mais les instincts proprement lupins — Meute, Hiérarchie et Pelages — ne sont pas universels. Chaque Lignée conserve donc sa propre morphologie et sa propre logique sociale.","carte":"**Voilé** : corps humain complet. Ni régénération, ni transformation, ni expression physique.\n\n**Semi-Révélé** : humain en apparence. Tes instincts, tes perceptions et les talents SR de ta Lignée commencent à percer.\n\n**Révélé — humain** : mains, parole, équipement. Talents R. Tu peux entamer une Mue.\n- *Régénération lente* : en humain révélé ou en animal, 1 PV par heure hors combat.\n\n**Révélé — animal** : la vraie forme de ta Lignée, donnée par son profil et ta Variante. 1 PA depuis l''humain révélé, sans épuisement.\n\n**Révélé — hybride (corps de guerre)** : les chiffres de ta Lignée, plus :\n- *Corps de guerre* : +3 Pugilat ; +2 PV au début de chaque round tant que tu vis et restes hybride.\n- *Rythme Khinae* : +1 PA par round, à partir du round qui suit la fin de la Mue.\n\n**Morphologie** : ton corps décide de ce qui est possible. Aucun profil ne crée des mains, une parole ou un usage d''équipement que ta forme n''a pas.\n\n**Mue hybride** : un round complet, sans autre action significative ; la forme est achevée au début du round suivant. Depuis le dernier vrai repos, test de Vigueur + Constitution :\n\n| Mue | 1re | 2e | 3e | 4e | 5e et + |\n|---|---|---|---|---|---|\n| Difficulté | Automatique | 15 | 18 | 21 | 25 |\n\nÉchec : tu peux forcer pour 3 PV irréductibles. Échec narratif : round perdu, plus de Mue hybride dans la scène.\n\n**Frénésie** : jamais spontanée ; seul un talent, un effet ou une situation qui le dit la déclenche.\n- *Impulsion* : un objet clair, donné par l''instinct de ta Lignée (un Tigre ne réagit pas comme un Requin ou un Ours). Au moins 1 PA par round pour le poursuivre.\n- −3 aux actions de calme et de concentration ; une violence simple, tir compris, reste possible.\n- La peur est écrasée pendant la Frénésie et revient après.\n- Sortie : Volonté + Maîtrise spirituelle 15 (12 si la cause a disparu).\n- *Pas de Meute* : personne n''est « reconnu » d''office et personne ne t''aide à sortir, sauf talent qui le dit.\n\n**Instinct de Lignée** : ta Frénésie et tes perceptions instinctives prennent l''animal de ta Lignée pour référence. Jamais d''Appel de la Meute, de Hiérarchie instinctive, de Bravoure lupine ni de Pelage.\n\n**Variante morphologique (gratuite)** : une espèce réelle de ta Lignée. Elle change gabarit, milieu, sens, venin ou robustesse. Ce n''est ni un talent ni un Sang ; elle ne s''achète pas et ne se change pas par PTV. **Quand une Variante donne des chiffres, ils remplacent ceux de l''hybride de la Lignée.**\n\n**Âme du Cycle** : à ta mort véritable, tu rejoins le Cycle.\n\n**Faiblesses** : pas de malédiction. Ton prix : une Mue lente et épuisante, la Frénésie, un corps lié à son milieu (un Requin hors de l''eau, un Crocodilien à terre), et la rareté : souvent, personne n''existe pour t''apprendre ce que tu es.\n\n*Corrections* : Régénération lente (trait #2) perdait la restriction « humain révélé ou animal » ; rétablie. La Frénésie Khinae renvoyait au « sous-système Garou » ; elle est écrite ici en entier, sans les règles de Meute (le chapitre dit « aucune Meute permanente n''est supposée »). Le sens des chiffres de Variante était ambigu (forme animale ou hybride ?) ; la carte tranche pour l''hybride, comme le font déjà le chapitre (Serpents : « base hybride ») et le Bestiaire.\n\n---","traits_gratuits":[{"name":"Âme du Cycle","access":"—","effect":"À sa mort véritable, le descendant de Khinae rejoint normalement le Cycle des âmes."},{"name":"Régénération lente","access":"R · humain révélé / animal","effect":"Récupère 1 PV par heure hors combat."},{"name":"Instinct de Lignée","access":"SR/R","effect":"La Frénésie et les perceptions instinctives prennent l’animal de la Lignée comme référence ; elles ne donnent ni Appel de la Meute ni Hiérarchie lupine par défaut."},{"name":"Corps de guerre","access":"R · hybride","effect":"En hybride : +3 aux tests de Pugilat et Régénération de 2 PV au début de chaque round tant que le personnage reste vivant et maintient la forme."},{"name":"Rythme Khinae","access":"R · hybride","effect":"À partir du round suivant l’achèvement de la Mue hybride : +1 PA à chaque round, au-delà du maximum normal."}],"choix_creation":["lignee","variante","sang_vif"],"maitrise":"Les Sangs vifs suivent la règle du Garou : un Sang est maîtrisé quand ses deux portes sont au palier II ; éveil d''un autre Sang : 3 PTV.","cout_eveil":3,"droits_acquis":"Les talents achetés avant les voies restent acquis ; les règles de voie valent pour les achats suivants (décision 20)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'khinae', 'khinae_lignee', 'Lignée', NULL, '{"nature":"khinae","gratuit":"Signature et Variante","choix":"unique_a_la_creation"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'khinae', 'khinae_sang_vif', 'Sang vif', NULL, '{"nature":"khinae","gratuit":null,"choix":"unique_a_la_creation","eveil":"3 PTV une fois le Sang maîtrisé","partage":"Garous (décision 10)"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'khinae', 'khinae_canides_errants', 'Canidés errants', NULL, '{"nature":"khinae","forme":"deux_portes_sommet","verrou":"ordre_paliers","lignee":"canides_errants","portes":{"A":"La poursuite","B":"Le relais"},"profil":"- **Animal** : +2 Agilité · Déplacement ×2 sur terrain adapté · morsure DGT 3 · odorat et ouïe de grand canidé.\n- **Hybride** : +3 Vigueur, +2 Agilité · DGT 5 · Armure 1 · Déplacement ×2.\n- **Variantes** : *Coyote* (friches, égouts et ville encombrée comptent comme terrain adapté) · *Chacal / Dhole* (charogne très décomposée tolérée ; distingue sang frais et charogne récente) · *Lycaon* (une poursuite continue ne s''arrête pas pour la seule fatigue ordinaire) · *Dingo* (chaleur et manque d''eau bien au-delà d''un humain).","impulsion":"la poursuite","description":"Coyotes, chacals, lycaons, dholes et dingos sont les descendants de Khinae ayant connu le plus de succès après les Loups. Sans société comparable aux Pelages, ils ont construit leur survie autour de la poursuite, de l’endurance et de la capacité à vivre sans territoire stable.","changements":"Relais de chasse noté [R] mais SR dans son texte → SR. Phrase de comparaison avec le Garou et le Grand Félin retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_canides_errants_piste_nomade', 'Piste nomade', NULL, '{"nature":"khinae","cout":0,"cout_actuel":0,"palier":"signature","porte":null,"acces":"SR","activation":null,"texte_court":"une odeur que tu as identifiée, tu la distingues du bruit olfactif ordinaire pour la scène. Elle ne crée aucune piste.","texte_reference":"une odeur que tu as identifiée, tu la distingues du bruit olfactif ordinaire pour la scène. Elle ne crée aucune piste.","lore":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'canides_errants_coyote_chacal_lycaon_dhole_et_dingo_talents_de_lignee_chemin_de_traverse_1_ptv_chemin_de_traverse', 'Chemin de traverse', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"A","acces":"R","activation":null,"texte_court":"en animal ou hybride, +3 aux tests de poursuite ou de fuite dans un terrain encombré mais franchissable. Les obstacles évidents restent sans jet.","texte_reference":"En Animal ou Hybride, gagnez +3 aux tests de poursuite ou fuite exploitant un terrain réellement encombré et franchissable. Les obstacles évidents restent sans jet ; aucun Déplacement supplémentaire ni passage à travers un obstacle impossible.\nSe distingue du Garou par la poursuite/fuite et du Grand Félin par le trajet : ni double bond ni auto-Assistance.","lore":"Les Canidés errants voient la ville et les terrains brisés comme une suite d’issues plutôt que d’obstacles. Talus, gravats, capots ou fenêtres basses deviennent des raccourcis de poursuite dès lors que leur corps peut réellement s’y engager.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_canides_errants_course_qui_ne_finit_pas', 'Course qui ne finit pas', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"A","acces":"R, animal ou hybride","activation":null,"texte_court":"tant que la poursuite continue reste ton objectif immédiat, la fatigue ordinaire ne réduit pas ton Déplacement et ne te fait pas perdre la piste. Faim, blessures, toxines, milieu hostile et épuisement surnaturel s''appliquent.","texte_reference":"tant que la poursuite continue reste ton objectif immédiat, la fatigue ordinaire ne réduit pas ton Déplacement et ne te fait pas perdre la piste. Faim, blessures, toxines, milieu hostile et épuisement surnaturel s''appliquent.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'canides_errants_coyote_chacal_lycaon_dhole_et_dingo_talents_de_lignee_relais_de_chasse_1_ptv_relais_de_chasse', 'Relais de chasse', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"B","acces":"SR","activation":null,"texte_court":"1 PA. Un allié qui t''entend ou te sent et poursuit la même proie reçoit direction, allure et changements brusques ; il reprend la poursuite sans redécouvrir la piste.","texte_reference":"SR — 1 PA Un allié pouvant l’entendre ou le sentir et poursuivant la même proie reçoit instinctivement direction, allure et changement brutal de trajectoire. Il peut reprendre une poursuite déjà acquise sans devoir redécouvrir de zéro la piste physique.\n1 PA ; l’allié doit réellement recevoir les signaux et poursuivre la même proie. Pas de télépathie mondiale ni de piste créée en absence de trace.","lore":"Une poursuite peut être passée à un allié presque comme une odeur partagée. Direction, allure et changement brutal de trajectoire lui parviennent par gestes et signaux instinctifs, assez pour reprendre le fil sans devoir retrouver seul la piste depuis son origine.","statut_regle":"correction","changements":"Accès R → SR. Relais de chasse noté [R] mais SR dans son texte → SR. Phrase de comparaison avec le Garou et le Grand Félin retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_canides_errants_piste_sous_les_pistes', 'Piste sous les pistes', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"B","acces":"SR","activation":null,"texte_court":"une piste déjà acquise reste identifiable malgré la foule, la pluie, la circulation, les autres animaux et la contamination olfactive ordinaire. Un moyen conçu pour effacer ou falsifier une trace peut encore demander une opposition.","texte_reference":"une piste déjà acquise reste identifiable malgré la foule, la pluie, la circulation, les autres animaux et la contamination olfactive ordinaire. Un moyen conçu pour effacer ou falsifier une trace peut encore demander une opposition.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_canides_errants_fermer_l_etau', 'Fermer l''étau', NULL, '{"nature":"khinae","cout":3,"cout_actuel":0,"palier":"III","porte":"sommet","acces":"R, 1/scène","activation":null,"texte_court":"quand une proie identifiée fuit par des moyens physiques et qu''une vraie route d''interception existe, le MJ t''indique une voie praticable pour tenter de couper sa trajectoire. Ne retrouve pas une proie perdue, ne traverse rien d''impossible.","texte_reference":"quand une proie identifiée fuit par des moyens physiques et qu''une vraie route d''interception existe, le MJ t''indique une voie praticable pour tenter de couper sa trajectoire. Ne retrouve pas une proie perdue, ne traverse rien d''impossible.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'khinae', 'khinae_renards', 'Renards libres', NULL, '{"nature":"khinae","forme":"deux_portes_sommet","verrou":"ordre_paliers","lignee":"renards","portes":{"A":"Les pistes","B":"Les odeurs et les sons"},"profil":"- **Animal** : +3 Agilité · Déplacement ×2 · morsure DGT 2 · excellente ouïe.\n- **Hybride** : +2 Vigueur, +3 Agilité · DGT 4 · Armure 1.\n- **Variantes** : *Roux* (référence, lisières et zones humaines peu denses) · *Fennec* (chaleur, écoute exceptionnelle) · *Arctique* (froid, camouflage neige et glace) · *Gris / forestier* (excellent grimpeur).","impulsion":"la fuite","description":"Les Renards Khinae libres sont rares : beaucoup de leurs anciennes lignées ont cédé à V’Aagor. Leur ruse surnaturelle n’est pas une illusion universelle ; elle agit surtout sur les traces laissées derrière eux — odeurs, sons, pistes et fausses directions.","changements":"Odeur empruntée notée [R] mais SR dans son texte → SR ; limites redites retirées."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_renards_odeur_mouvante', 'Odeur mouvante', NULL, '{"nature":"khinae","cout":0,"cout_actuel":0,"palier":"signature","porte":null,"acces":"SR","activation":null,"texte_court":"tu atténues, accentues ou déformes ta propre odeur, sans encore copier celle d''un individu.","texte_reference":"tu atténues, accentues ou déformes ta propre odeur, sans encore copier celle d''un individu.","lore":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'renards_les_survivants_libres_talents_de_lignee_piste_bifurquee_1_ptv_piste_bifurquee', 'Piste bifurquée', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"A","acces":"R","activation":null,"texte_court":"1/scène, pendant un Déplacement payé en animal ou hybride, ta trace se dédouble sur deux itinéraires plausibles, 20 m au plus. Le pisteur oppose Esprit + Perception à ton Agilité + Furtivité ; la fausse piste finit par mourir.","texte_reference":"Une fois par scène, pendant un Déplacement payé en Animal ou Hybride, faites diverger votre trace sur deux itinéraires plausibles pendant 20 m maximum. Le pisteur oppose Esprit + Perception à votre Agilité + Furtivité pour départager les traces ; la fausse finit par s’éteindre.\nNe trompe pas quelqu’un qui vous suit réellement des yeux et ne produit pas une créature autonome. ","lore":"Le Renard apprend à faire mentir jusqu’à sa propre trace. Pendant une courte distance, odeurs et micro-indices dessinent deux chemins plausibles ; l’un mène au prédateur, l’autre s’éteint seulement après avoir coûté du temps au pisteur.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_renards_corps_d_echappee', 'Corps d''échappée', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"A","acces":"R, Réaction, 1 PA, 1/scène","activation":null,"texte_court":"saisi, ligoté ou coincé par une contrainte purement physique, tu tords ou comprimes ton corps pour te libérer si une issue corporelle existe. Un scellement surnaturel ou une cage sans ouverture tient.","texte_reference":"saisi, ligoté ou coincé par une contrainte purement physique, tu tords ou comprimes ton corps pour te libérer si une issue corporelle existe. Un scellement surnaturel ou une cage sans ouverture tient.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'renards_les_survivants_libres_talents_de_lignee_odeur_empruntee_1_ptv_odeur_empruntee', 'Odeur empruntée', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"B","acces":"SR","activation":null,"texte_court":"1 PA. Après contact avec une source olfactive fraîche, tu reproduis son odeur naturelle pour la scène. Trompe l''odorat ordinaire et animal, pas une signature surnaturelle ni la biométrie.","texte_reference":"SR — 1 PA Après contact avec une source olfactive fraîche, le Renard peut reproduire son odeur naturelle pour la scène. Cela trompe l’odorat ordinaire et animal, pas une signature surnaturelle, biométrique ou un observateur ayant d’autres preuves.\n1 PA, contact olfactif frais, pour la scène ; pas de signature surnaturelle, d’identité complète ou d’oubli des autres preuves.","lore":"Après avoir recueilli une odeur fraîche, le Renard peut la porter comme un masque olfactif. Les nez ordinaires et animaux rencontrent alors la signature empruntée plutôt que la sienne, tant qu’aucune autre preuve ou perception surnaturelle ne vient contredire le mensonge.","statut_regle":"correction","changements":"Accès R → SR. Odeur empruntée notée [R] mais SR dans son texte → SR ; limites redites retirées."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_renards_voix_de_l_autre_cote', 'Voix de l''autre côté', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"B","acces":"R, 1 PA","activation":null,"texte_court":"tu projettes ta voix, un cri ou un son simple depuis un point visible ou connu à courte portée. Rien ne traverse un obstacle qui étoufferait le son ; ni image ni pensée.","texte_reference":"tu projettes ta voix, un cri ou un son simple depuis un point visible ou connu à courte portée. Rien ne traverse un obstacle qui étoufferait le son ; ni image ni pensée.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_renards_le_faux_renard', 'Le Faux Renard', NULL, '{"nature":"khinae","cout":3,"cout_actuel":0,"palier":"III","porte":"sommet","acces":"R, 2 PA, 1/scène","activation":null,"texte_court":"une fausse présence d''odeurs, de bruits et de pas part dans la direction choisie. Une créature qui ne te voit plus et suit ces traces doit vaincre ta Volonté + Maîtrise spirituelle, sinon elle suit le mauvais départ. Tu n''es jamais invisible.","texte_reference":"une fausse présence d''odeurs, de bruits et de pas part dans la direction choisie. Une créature qui ne te voit plus et suit ces traces doit vaincre ta Volonté + Maîtrise spirituelle, sinon elle suit le mauvais départ. Tu n''es jamais invisible.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'khinae', 'khinae_grands_felins', 'Grands Félins', NULL, '{"nature":"khinae","forme":"deux_portes_sommet","verrou":"ordre_paliers","lignee":"grands_felins","portes":{"A":"L''approche","B":"La prise"},"profil":"- **Animal** : +2 Vigueur, +2 Agilité · Déplacement ×2 · griffes et crocs DGT 4 · sens de prédateur.\n- **Hybride** : +4 Vigueur, +2 Agilité · DGT 6 · Armure 1 · Déplacement ×2 *(Armure 2 → 1, B2 validé)*.\n- **Variantes** : *Tigre* (référence, excellent nageur) · *Lion* (+4 Vigueur / +1 Agilité ; peut reconnaître une petite troupe durable, sans règle de Meute) · *Panthère* (+3 / +3, DGT 5, Armure 1 ; escalade et nuit) · *Jaguar* (référence ; eau et végétation dense ; les libres de Quetzal sont rares) · *Puma* (+3 / +3, DGT 5, Armure 1 ; montagne et changements d''altitude).","impulsion":"la proie isolée","description":"Tigres, Lions, Panthères, Jaguars et Pumas comptent parmi les Khinae les plus redoutables individuellement et les moins enclins à bâtir de grandes sociétés. Leur Nature privilégie embuscade, bond, discrétion et domination physique d’une proie isolée.","changements":"note de développement retirée (« le modèle doit connaître la distance de bond »). Mort dans l''angle mort ressemble à Embuscade parfaite (Garou) et Ombre prédatrice (Vampire) ; son ressort propre est déjà là : pas de pouvoir d''invisibilité, une vraie dissimulation (le couvert du fauve), une fois par scène."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_grands_felins_silence_du_grand_fauve', 'Silence du grand fauve', NULL, '{"nature":"khinae","cout":0,"cout_actuel":0,"palier":"signature","porte":null,"acces":"SR","activation":null,"texte_court":"si tu as déjà un couvert ou une dissimulation crédible, tes déplacements naturels ne trahissent pas ta position. Pas d''invisibilité ; un sol vraiment bruyant reste bruyant.","texte_reference":"si tu as déjà un couvert ou une dissimulation crédible, tes déplacements naturels ne trahissent pas ta position. Pas d''invisibilité ; un sol vraiment bruyant reste bruyant.","lore":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'grands_felins_tigres_et_lignees_apparentees_talents_de_lignee_bond_souverain_1_ptv_bond_souverain', 'Bond souverain', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"A","acces":"R","activation":null,"texte_court":"en animal ou hybride, double la distance d''un bond de ta forme, dans la limite du Déplacement payé, avec une réception praticable. Ni second Déplacement ni vol.","texte_reference":"En Animal ou Hybride, doublez la distance normale d’un bond de votre forme, dans la limite du Déplacement payé, avec une réception réellement praticable. Cela n’accorde ni second Déplacement ni vol et un exploit extrême peut encore demander un test.\nLe double porte sur le bond, pas sur toute la vitesse déjà multipliée du profil. Le modèle doit connaître la distance de bond de référence avant de la multiplier.","lore":"Le Grand Félin traite hauteur et distance comme des mesures différentes de celles d’un humain. Ses bonds ordinaires couvrent des intervalles déjà extraordinaires pour un bipède, sans que chaque corniche ou changement de niveau devienne un exploit conscient.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_grands_felins_approche_d_angle_mort', 'Approche d''angle mort', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"A","acces":"R","activation":null,"texte_court":"si tu commences ton activation non localisé et qu''un parcours couvert existe jusqu''à courte portée, le seul bruit de ton mouvement ne te trahit pas. Une ligne de vue directe ou un capteur adapté te détecte.","texte_reference":"si tu commences ton activation non localisé et qu''un parcours couvert existe jusqu''à courte portée, le seul bruit de ton mouvement ne te trahit pas. Une ligne de vue directe ou un capteur adapté te détecte.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'grands_felins_tigres_et_lignees_apparentees_talents_de_lignee_saisie_du_fauve_1_ptv_saisie_du_fauve', 'Saisie du fauve', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"B","acces":"R","activation":null,"texte_court":"1/round, après une attaque naturelle payée qui inflige au moins 1 PV, tu engages une saisie sans PA ni jet de plus sur une cible de gabarit compatible. Elle se libère par l''opposition physique normale.","texte_reference":"Une fois par round, après une attaque naturelle payée infligeant au moins 1 PV réel, engagez immédiatement une saisie sans PA supplémentaire ni second jet sur une cible de gabarit compatible. La libération suit ensuite l’opposition physique normale.\nNe donne pas les dégâts d’une deuxième attaque. Un effet qui empêche physiquement la prise reste opposable ; pas de contrôle d’une cible gigantesque par simple réussite d’attaque.","lore":"L’attaque naturelle se prolonge immédiatement en contrôle de la proie. Griffes, masse et élan permettent au Grand Félin d’accrocher un adversaire compatible avant qu’il ne profite du recul pour sortir de portée.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_grands_felins_duel_du_predateur', 'Duel du prédateur', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"B","acces":"R, 1 PA, 1/scène","activation":null,"texte_court":"tu désignes une proie perçue. Jusqu''à la fin de la scène, ou jusqu''à ce que tu changes de cible, elle ne peut pas te Surprendre par une feinte ou un mouvement purement physique dans cette confrontation. Aucun bonus contre les autres.","texte_reference":"tu désignes une proie perçue. Jusqu''à la fin de la scène, ou jusqu''à ce que tu changes de cible, elle ne peut pas te Surprendre par une feinte ou un mouvement purement physique dans cette confrontation. Aucun bonus contre les autres.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_grands_felins_mort_dans_l_angle_mort', 'Mort dans l''angle mort', NULL, '{"nature":"khinae","cout":3,"cout_actuel":0,"palier":"III","porte":"sommet","acces":"R, 1/scène","activation":null,"texte_court":"si la cible ne t''avait pas localisé au début de ton activation, ta première attaque naturelle depuis une vraie dissimulation la traite comme Surprise. Il faut qu''elle ait réellement perdu ta position.","texte_reference":"si la cible ne t''avait pas localisé au début de ton activation, ta première attaque naturelle depuis une vraie dissimulation la traite comme Surprise. Il faut qu''elle ait réellement perdu ta position.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15). note de développement retirée (« le modèle doit connaître la distance de bond »). Mort dans l''angle mort ressemble à Embuscade parfaite (Garou) et Ombre prédatrice (Vampire) ; son ressort propre est déjà là : pas de pouvoir d''invisibilité, une vraie dissimulation (le couvert du fauve), une fois par scène."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'khinae', 'khinae_chats', 'Chats', NULL, '{"nature":"khinae","forme":"deux_portes_sommet","verrou":"ordre_paliers","lignee":"chats","portes":{"A":"Les chutes","B":"Les passages"},"profil":"- **Animal** : +4 Agilité · petit gabarit · griffes et morsure DGT 1 · Déplacement ×2 en terrain encombré.\n- **Hybride** : +1 Vigueur, +4 Agilité · DGT 3 · Armure 0.\n- **Variantes** : *Domestique* (crédible comme chat ordinaire) · *Sauvage* (+2 Vigueur / +3 Agilité, DGT 4, Armure 1 ; plus dur à banaliser) · *Nocturne* (à l''aise en faible lumière) · *Grimpeur* (les surfaces verticales comptent comme terrain normal).","impulsion":"l''issue","description":"Les petits Félins ont survécu moins par puissance brute que par curiosité, diplomatie et capacité à vivre au voisinage d’êtres beaucoup plus dangereux. Un Chat peut devenir intermédiaire entre monstres sans jamais accepter d’être le familier ou le serviteur de qui que ce soit.","changements":"accès recopié dans le texte de Passer partout retiré."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_chats_inoffensif_par_nature', 'Inoffensif par nature', NULL, '{"nature":"khinae","cout":0,"cout_actuel":0,"palier":"signature","porte":null,"acces":"SR","activation":null,"texte_court":"un instinct qui ne connaît que « prédateur dangereux » ne te classe pas d''office comme menace majeure tant que tu ne montres pas d''hostilité. N''efface aucune preuve.","texte_reference":"un instinct qui ne connaît que « prédateur dangereux » ne te classe pas d''office comme menace majeure tant que tu ne montres pas d''hostilité. N''efface aucune preuve.","lore":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'chats_les_familiers_de_personne_talents_de_lignee_toujours_retomber_1_ptv_toujours_retomber', 'Toujours retomber', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"A","acces":"R","activation":null,"texte_court":"en animal ou hybride, une chute compte comme 6 m moins haute (minimum zéro) si tu as la place de te retourner et une surface de réception viable.","texte_reference":"En Animal ou Hybride, calculez la chute comme si elle était 6 m moins haute, minimum zéro, si vous avez l’espace de vous retourner et une surface de réception viable. Aucun effet contre une réception meurtrière, l’écrasement ou une chute dont l’excédent reste dangereux.\nAppliquer ensuite les règles normales de chute à la hauteur restante. Ce n’est pas une immunité universelle aux chutes.","lore":"Dans la chute, le Chat retrouve son orientation avant que la panique n’ait le temps de s’installer. Colonne, pattes et équilibre corrigent la réception tant qu’un minimum d’espace et une surface plausible lui laissent quelque chose sur quoi retomber.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_chats_neuf_issues', 'Neuf issues', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"A","acces":"R, Réaction, 1 PA, 1/round","activation":null,"texte_court":"après avoir subi ou évité une agression au contact, tu rejoins un perchoir, un couvert, un rebord ou un passage à ta portée avant que la même source n''enchaîne.","texte_reference":"après avoir subi ou évité une agression au contact, tu rejoins un perchoir, un couvert, un rebord ou un passage à ta portée avant que la même source n''enchaîne.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'chats_les_familiers_de_personne_talents_de_lignee_passer_partout_1_ptv_passer_partout', 'Passer partout', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"B","acces":"R","activation":null,"texte_court":"en animal, toute ouverture qui admet ton crâne ; en hybride, des passages bien trop étroits pour un humain si ton ossature peut s''y engager.","texte_reference":"R — Animal/Hybride En animal, le Chat peut franchir toute ouverture réellement compatible avec son crâne et comprimer le reste du corps de manière anormale. En hybride, il peut traverser des passages beaucoup trop étroits pour un humain ordinaire si sa structure osseuse peut raisonnablement s’y engager.\nL’ouverture doit admettre le crâne ou l’ossature pertinente ; pas de passage à travers la matière, d’équipement comprimé automatiquement ou de corps désarticulé sans limite.","lore":"Le Chat considère son crâne, non ses épaules, comme la véritable mesure d’un passage. Son corps se comprime avec une souplesse anormale et transforme fentes, conduits ou ouvertures étroites en chemins praticables tant que l’ossature peut réellement les franchir.","statut_regle":"correction","changements":"accès recopié dans le texte de Passer partout retiré."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_chats_entre_les_monstres', 'Entre les monstres', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"B","acces":"SR/R, Réaction, 1 PA, 1/scène","activation":null,"texte_court":"dans un échange direct avec une créature surnaturelle, tu sens l''instant où il bascule vers une agression contre toi : Défense active, déplacement simple ou manipulation préparée avant la résolution. Ne lit aucune pensée.","texte_reference":"dans un échange direct avec une créature surnaturelle, tu sens l''instant où il bascule vers une agression contre toi : Défense active, déplacement simple ou manipulation préparée avant la résolution. Ne lit aucune pensée.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_chats_familier_de_personne', 'Familier de personne', NULL, '{"nature":"khinae","cout":3,"cout_actuel":0,"palier":"III","porte":"sommet","acces":"R, Réaction, 1 PA, 1/scène","activation":null,"texte_court":"quand un pouvoir cherche à te posséder, à te lier comme familier ou à faire de toi la propriété spirituelle de quelqu''un, tu opposes Volonté + Force Mentale même si l''effet n''offre aucune défense. En réussite, cette source ne peut retenter de la scène.","texte_reference":"quand un pouvoir cherche à te posséder, à te lier comme familier ou à faire de toi la propriété spirituelle de quelqu''un, tu opposes Volonté + Force Mentale même si l''effet n''offre aucune défense. En réussite, cette source ne peut retenter de la scène.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'khinae', 'khinae_rapaces', 'Rapaces', NULL, '{"nature":"khinae","forme":"deux_portes_sommet","verrou":"ordre_paliers","lignee":"rapaces","portes":{"A":"Le regard","B":"Les perchoirs"},"profil":"- **Animal** : +3 Agilité · serres et bec DGT 3 · Bond ailé · sens selon la Variante.\n- **Hybride** : +2 Vigueur, +3 Agilité · serres DGT 5 · Armure 1 · Bond ailé.\n- **Variantes** : *Aigle* (+3 Vigueur / +2 Agilité ; vue longue) · *Faucon* (+1 / +4 ; vitesse horizontale) · *Hibou* (+1 / +3 ; nuit, battements silencieux) · *Vautour* (+2 / +2 ; charogne, endurance).","impulsion":"la proie vue d''en haut","description":"Aigles, Faucons, Hiboux et Vautours sont des Khinae construits autour des hauteurs, de la perception et du mouvement aérien. Leur forme animale ouvre une géographie inaccessible aux lignées terrestres, mais leur corps et leur équipement restent soumis aux limites réelles de leur morphologie.","changements":"préfixe d''accès retiré du texte de Perchoir impossible."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_rapaces_bond_aile', 'Bond ailé', NULL, '{"nature":"khinae","cout":0,"cout_actuel":0,"palier":"signature","porte":null,"acces":"R, animal ou hybride","activation":null,"texte_court":"un Déplacement franchit un vide, gagne ou perd beaucoup d''altitude et ignore les obstacles au sol ; distance ×2 environ si la trajectoire s''y prête. Tu dois finir sur un support.","texte_reference":"un Déplacement franchit un vide, gagne ou perd beaucoup d''altitude et ignore les obstacles au sol ; distance ×2 environ si la trajectoire s''y prête. Tu dois finir sur un support.","lore":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'rapaces_aigles_faucons_hiboux_et_vautours_talents_de_lignee_vue_plongeante_1_ptv_vue_plongeante', 'Vue plongeante', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"A","acces":"R","activation":null,"texte_court":"depuis une position élevée, +3 en Perception visuelle lointaine ; tu ignores jusqu''à −3 dû à la seule distance.","texte_reference":"Depuis une position élevée, gagnez +3 aux tests de Perception visuelle lointaine et ignorez jusqu’à −3 dus à la seule distance pour distinguer un détail physiquement visible. Ni vision à travers obstacle, ni lecture de Vérité cachée, ni bonus de Tir automatique.\nNe cumule pas deux bonus favorables substantiellement équivalents de même sens. La portée matérielle et les conditions d’observation doivent encore permettre l’image.","lore":"Depuis les hauteurs, le Rapace distingue mouvement et silhouette à des distances où l’œil humain ne reçoit plus qu’une masse vague. Cette précision reste une vision naturelle exceptionnelle : aucun mur ni secret de Vérité ne devient transparent.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_rapaces_plongeon_de_chasse', 'Plongeon de chasse', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"A","acces":"R, animal ou hybride","activation":null,"texte_court":"après une nette perte d''altitude pendant un Bond ailé, une attaque naturelle qui inflige au moins 1 PV peut, comme Altération, renverser la cible ou lui arracher un objet, si le gabarit le permet. Aucun DGT de plus.","texte_reference":"après une nette perte d''altitude pendant un Bond ailé, une attaque naturelle qui inflige au moins 1 PV peut, comme Altération, renverser la cible ou lui arracher un objet, si le gabarit le permet. Aucun DGT de plus.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'rapaces_aigles_faucons_hiboux_et_vautours_talents_de_lignee_perchoir_impossible_1_ptv_perchoir_impossible', 'Perchoir impossible', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"B","acces":"R","activation":null,"texte_court":"un Bond ailé peut finir sur une corniche minuscule, un poteau, un câble ou une façade qui offre une prise. Un support sur la trajectoire d''une chute peut l''arrêter.","texte_reference":"R — Animal/Hybride Peut terminer un Bond ailé sur une corniche minuscule, un poteau, une branche étroite, un câble ou une façade offrant réellement une prise. Si une chute laisse un support saisissable sur sa trajectoire, il peut l’utiliser pour arrêter sa descente.\nRespecter les contraintes de support et de masse réellement soutenable. Aucun vol stationnaire ou vol soutenu ajouté en contradiction avec le profil actuel des Rapaces.","lore":"Un appui que l’homme appellerait dérisoire suffit au Rapace. Câble, corniche, branche ou aspérité deviennent un véritable perchoir, et même une chute peut être interrompue si une prise assez solide traverse sa trajectoire.","statut_regle":"correction","changements":"préfixe d''accès retiré du texte de Perchoir impossible."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_rapaces_emporter', 'Emporter', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"B","acces":"R, animal ou hybride","activation":null,"texte_court":"une cible ou un objet déjà saisi et assez léger peut être emporté pendant un Bond ailé. Pas de vol stationnaire : tu finis sur un support, et ta Vigueur dit ce que tu portes.","texte_reference":"une cible ou un objet déjà saisi et assez léger peut être emporté pendant un Bond ailé. Pas de vol stationnaire : tu finis sur un support, et ta Vigueur dit ce que tu portes.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_rapaces_traversee_des_hauteurs', 'Traversée des hauteurs', NULL, '{"nature":"khinae","cout":3,"cout_actuel":0,"palier":"III","porte":"sommet","acces":"R, 1/scène","activation":null,"texte_court":"un même Déplacement enchaîne jusqu''à trois appuis atteignables (toit, balcon, enseigne, arbre, pylône) sans revenir au sol. Chaque étape reste un Bond ; tu finis sur un support.","texte_reference":"un même Déplacement enchaîne jusqu''à trois appuis atteignables (toit, balcon, enseigne, arbre, pylône) sans revenir au sol. Chaque étape reste un Bond ; tu finis sur un support.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'khinae', 'khinae_requins', 'Requins', NULL, '{"nature":"khinae","forme":"deux_portes_sommet","verrou":"ordre_paliers","lignee":"requins","portes":{"A":"Le sang","B":"Le courant"},"profil":"- **Animal** (exige l''eau) : +2 Agilité · nage très rapide · morsure DGT 4 · perçoit la pression et l''odeur du sang. Hors de l''eau, devient non fonctionnel à terme.\n- **Hybride** : dans l''eau, +4 Vigueur, +2 Agilité · morsure DGT 6 · Armure 2. Sur terre, perd le bonus d''Agilité et subit les contraintes de son corps.\n- **Variantes** : *Blanc* (référence ; profondeur et froid) · *Bouledogue* (+3 / +2, DGT 5, Armure 2 ; eau douce et salée) · *Tigre* (robuste, digestion opportuniste) · *Marteau* (+3 / +3, DGT 5, Armure 1 ; électroréception) · *Baleine* (+5 / +1, DGT 4, Armure 3 ; très grand gabarit).","impulsion":"le sang dans l''eau","description":"Les Requins sont des prédateurs Khinae marins dont la vie sociale et la chasse s’organisent autour de littoraux, ports, profondeurs et installations aquatiques. Vitesse, pression, sang et électroréception remplacent les repères territoriaux d’un prédateur terrestre.","changements":"phrase de distinction avec le Sang Écarlate retirée (renvoi à un pouvoir Garou). Variante Baleine : « moins prédateur » dans le trait, mais +5 Vigueur et Armure 3 dans les règles ; chiffres rétablis."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_requins_sang_qui_refuse_l_abysse', 'Sang qui refuse l''abysse', NULL, '{"nature":"khinae","cout":0,"cout_actuel":0,"palier":"signature","porte":null,"acces":null,"activation":null,"texte_court":"1/scène, relance d''une exposition biologique à la Corruption de Thul venue d''un milieu abyssal, d''un tissu ou d''une créature thulienne.","texte_reference":"1/scène, relance d''une exposition biologique à la Corruption de Thul venue d''un milieu abyssal, d''un tissu ou d''une créature thulienne.","lore":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'requins_les_independants_des_abysses_talents_de_lignee_sang_dans_leau_1_ptv_sang_dans_leau', 'Sang dans l''eau', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"A","acces":"SR/R, dans l''eau","activation":null,"texte_court":"direction générale d''une créature qui saigne dans la même masse d''eau, à 100 m au plus. Ni identité ni distance exacte.","texte_reference":"En SR/R dans l’eau, percevez la direction générale d’une créature qui saigne réellement dans une masse d’eau connectée à 100 m maximum. Pas d’identité, de distance exacte ni de détection à travers une séparation étanche.\nDistinguer cette détection d’un saignement actif de l’étude d’une signature individuelle par le Sang Écarlate.","lore":"Une blessure ouverte dans une masse d’eau connectée devient un appel directionnel. Le Requin ne reçoit ni nom ni distance parfaite, seulement la certitude instinctive qu’un être saigne quelque part dans cette direction.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_requins_morsure_verrouillee', 'Morsure verrouillée', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"A","acces":"R, animal ou hybride, 1/round","activation":null,"texte_court":"après une morsure qui inflige au moins 1 PV, tu verrouilles la prise. La cible ne quitte pas le contact par un simple Déplacement : elle doit briser la saisie par opposition physique ou un moyen approprié.","texte_reference":"après une morsure qui inflige au moins 1 PV, tu verrouilles la prise. La cible ne quitte pas le contact par un simple Déplacement : elle doit briser la saisie par opposition physique ou un moyen approprié.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'requins_les_independants_des_abysses_talents_de_lignee_lecture_electrique_1_ptv_lecture_electrique', 'Lecture électrique', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"B","acces":"SR/R, dans l''eau","activation":null,"texte_court":"tu localises l''activité bioélectrique des vivants à 10 m, +3 Perception pour les distinguer, même sans vision. Les isolants adaptés bloquent.","texte_reference":"En SR/R dans l’eau, localisez l’activité bioélectrique de créatures vivantes à 10 m et gagnez +3 en Perception pour la distinguer précisément, même sans vision. Le Requin-marteau conserve son sens inné ; le talent en approfondit la précision, sans ignorer isolants ou contre-mesures adaptés.\nAucun affichage des pensées ou diagnostic médical complet.","lore":"Dans l’eau, le Requin perçoit les faibles champs produits par les organismes vivants. L’obscurité totale n’abolit donc pas une présence proche : cœur, nerfs et muscles écrivent encore dans le milieu un signal que cette lignée sait lire.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_requins_corps_des_profondeurs', 'Corps des profondeurs', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"B","acces":"R, animal ou hybride","activation":null,"texte_court":"pressions océaniques extrêmes, froid abyssal et variations de profondeur ordinaires ne rendent plus ton corps non fonctionnel. Rien contre un froid surnaturel ou une décompression imposée par un pouvoir.","texte_reference":"pressions océaniques extrêmes, froid abyssal et variations de profondeur ordinaires ne rendent plus ton corps non fonctionnel. Rien contre un froid surnaturel ou une décompression imposée par un pouvoir.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_requins_predateur_du_courant', 'Prédateur du courant', NULL, '{"nature":"khinae","cout":3,"cout_actuel":0,"palier":"III","porte":"sommet","acces":"R, Réaction, 1 PA, 1/scène","activation":null,"texte_court":"une cible perçue tente de quitter la zone par la même masse d''eau : si une route existe, tu te déplaces aussitôt pour couper son trajet. Ni déplacement impossible ni attaque gratuite.","texte_reference":"une cible perçue tente de quitter la zone par la même masse d''eau : si une route existe, tu te déplaces aussitôt pour couper son trajet. Ni déplacement impossible ni attaque gratuite.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'khinae', 'khinae_serpents', 'Serpents', NULL, '{"nature":"khinae","forme":"deux_portes_sommet","verrou":"ordre_paliers","lignee":"serpents","portes":{"A":"Le guet","B":"Le corps"},"profil":"- **Animal** : +3 Agilité · locomotion ophidienne · morsure DGT 2 ou 3 selon la Variante.\n- **Hybride (selon la Variante)** :\n  - *Vipère* : +2 Vigueur, +3 Agilité, DGT 3, Armure 1. Venin hémotoxique : une morsure qui inflige au moins 1 PV impose Vigueur + Constitution 15 ; en échec, 1 PV irréductible au début de ses deux prochaines activations. Une exposition par cible et par scène.\n  - *Cobra* : +2 / +2, DGT 3, Armure 1. Venin neurotoxique, difficulté 15 ; en échec, 1 PA au plus d''actions physiques à sa prochaine activation. Une exposition par cible et par scène.\n  - *Python / Boa* : +4 / +1, DGT 4, Armure 2 ; pas de venin ; la saisie sert de constriction.\n  - *Couleuvre* : +1 / +4, DGT 2, Armure 0 ; passages très étroits.","impulsion":"ce qui entre au contact","description":"Les Serpents regroupent lignées venimeuses, constrictrices et furtives. Leur variante morphologique détermine l’arme biologique principale et leur rapport à l’attente, à la chaleur et à l’économie de mouvement diffère profondément de celui des mammifères Khinae.","changements":"« l''attaque n''est pas gratuite » redit deux fois, retiré. Sens du vivant : le Bestiaire dit « proches » ; la portée de 10 m est ajoutée pour le joueur."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_serpents_corps_ophidien', 'Corps ophidien', NULL, '{"nature":"khinae","cout":0,"cout_actuel":0,"palier":"signature","porte":null,"acces":"R, animal ou hybride","activation":null,"texte_court":"tu avances sans membres, t''enroules aux supports et comprimes ton corps comme aucun humain.","texte_reference":"tu avances sans membres, t''enroules aux supports et comprimes ton corps comme aucun humain.","lore":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'serpents_venimeux_constricteurs_et_lignees_furtives_talents_de_lignee_frappe_ophidienne_1_ptv_frappe_ophidienne', 'Frappe ophidienne', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"A","acces":"R","activation":null,"texte_court":"Réaction, 1 PA, 1/round. Quand une cible que tu perçois entre volontairement à ton contact, tu portes une attaque naturelle normale avant qu''elle poursuive son action.","texte_reference":"R — Réaction 1 PA — 1/round Lorsqu’une cible entre volontairement au contact du Serpent et qu’il la perçoit, il peut immédiatement effectuer une attaque naturelle normale avant la poursuite de son action. L’attaque coûte bien le PA de Réaction et n’est pas gratuite.\n1 PA en Réaction, 1/round ; cible qui entre volontairement au contact et est perçue. L’attaque n’est pas gratuite et ne déclenche pas une boucle entre plusieurs réactions.","lore":"Le Serpent attend l’entrée dans sa distance plutôt que de poursuivre. Lorsqu’une cible vient volontairement au contact, cou, mâchoire ou corps partent dans un réflexe fulgurant avant que l’intrus n’ait achevé son propre mouvement.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_serpents_arme_ophidienne_perfectionnee', 'Arme ophidienne perfectionnée', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"A","acces":"R","activation":null,"texte_court":"ta Variante se renforce. *Vipère* : venin hémotoxique à 18. *Cobra* : venin neurotoxique à 18. *Python / Boa* : une cible saisie ne s''échappe par Déplacement ou transformation purement physique qu''en gagnant une opposition de Vigueur. *Couleuvre* : après une attaque naturelle, tu te retires dans un passage de ton gabarit par un Déplacement normal sans perdre ta dissimulation.","texte_reference":"ta Variante se renforce. *Vipère* : venin hémotoxique à 18. *Cobra* : venin neurotoxique à 18. *Python / Boa* : une cible saisie ne s''échappe par Déplacement ou transformation purement physique qu''en gagnant une opposition de Vigueur. *Couleuvre* : après une attaque naturelle, tu te retires dans un passage de ton gabarit par un Déplacement normal sans perdre ta dissimulation.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'serpents_venimeux_constricteurs_et_lignees_furtives_talents_de_lignee_mue_de_peau_1_ptv_mue_de_peau', 'Mue de peau', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"B","acces":"R","activation":null,"texte_court":"1 PA, 1/scène. Tu abandonnes une couche de peau et ce qui n''est fixé qu''à elle (colle, poudre, parasite, traceur). Ni implant profond, ni blessure, ni Corruption.","texte_reference":"Pour 1 PA en R, une fois par scène, abandonnez une couche de peau et les colles, poudres, parasites externes ou dispositifs fixés uniquement à cette surface. Ni implant profond, blessure, lien spirituel ou Corruption n’est retiré.\nNe produit pas de guérison ; un dispositif ancré dans un tissu profond ne part pas avec l’enveloppe.","lore":"Une couche superficielle peut être abandonnée avec tout ce qu’elle porte. Colle, poudre, parasite ou trace fixée sur la peau reste sur l’ancienne enveloppe, tandis que ce qui est ancré dans l’essence du Serpent demeure évidemment avec lui.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_serpents_sens_du_vivant', 'Sens du vivant', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"B","acces":"SR/R","activation":null,"texte_court":"par la langue, les vibrations, la chaleur ou l''électrochimie selon ta Variante, tu perçois la présence et la direction des vivants proches, même sans les voir. Un obstacle étanche ou une isolation adaptée bloque ce sens.","texte_reference":"par la langue, les vibrations, la chaleur ou l''électrochimie selon ta Variante, tu perçois la présence et la direction des vivants proches, même sans les voir. Un obstacle étanche ou une isolation adaptée bloque ce sens.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15). « l''attaque n''est pas gratuite » redit deux fois, retiré. Sens du vivant : le Bestiaire dit « proches » ; la portée de 10 m est ajoutée pour le joueur."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_serpents_corps_sans_angles', 'Corps sans angles', NULL, '{"nature":"khinae","cout":3,"cout_actuel":0,"palier":"III","porte":"sommet","acces":"R, 2 PA, 1/scène","activation":null,"texte_court":"tu disloques, comprimes ou réorganises ton corps pour sortir d''une contrainte purement physique ou franchir un passage que ton hybride ne devrait pas accepter. Le crâne, les organes vitaux et l''existence d''une ouverture restent des limites.","texte_reference":"tu disloques, comprimes ou réorganises ton corps pour sortir d''une contrainte purement physique ou franchir un passage que ton hybride ne devrait pas accepter. Le crâne, les organes vitaux et l''existence d''une ouverture restent des limites.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'khinae', 'khinae_boudas', 'Boudas', NULL, '{"nature":"khinae","forme":"deux_portes_sommet","verrou":"ordre_paliers","lignee":"boudas","portes":{"A":"La curée","B":"La Bande"},"profil":"- **Animal** : +2 Vigueur, +2 Agilité · morsure DGT 4 · excellente digestion.\n- **Hybride** : +3 Vigueur, +2 Agilité · morsure DGT 6 · Armure 2.\n- **Variantes** : *Tachetée* (+4 Vigueur / +1 Agilité) · *Rayée* (+2 / +3 ; mobile et discrète) · *Brune* (référence ; charogne et aridité).","impulsion":"la proie blessée de la Bande","description":"Les Boudas sont des Hommes-Hyènes sociaux, organisés autour de Bandes plutôt que de Meutes lupines. Leur cohésion est réelle mais suit ses propres codes, et leurs lignées combinent robustesse, charognage et agressivité collective sans acquérir gratuitement les traditions de Pelage.","changements":"le trait Bande de ricanement disait « pour les Talents de Lignée » : les trois talents du livre (Harcèlement tournant, Rire de ralliement, La Bande rit encore) en sont l''usage. Harcèlement tournant ressemble à Chasse coordonnée (Garou, Pelage Noir) ; son ressort propre est déjà là : la Bande d''une scène, pas une Meute, et le déclencheur est la blessure infligée par n''importe quel membre. Exclusion surnaturelle redite, retirée de Mâchoire broyeuse."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_boudas_bande_de_ricanement', 'Bande de ricanement', NULL, '{"nature":"khinae","cout":0,"cout_actuel":0,"palier":"signature","porte":null,"acces":null,"activation":null,"texte_court":"au début d''une scène ou d''une chasse, jusqu''à trois créatures consentantes deviennent ta Bande pour la scène. Ni Meute permanente, ni obligation.","texte_reference":"au début d''une scène ou d''une chasse, jusqu''à trois créatures consentantes deviennent ta Bande pour la scène. Ni Meute permanente, ni obligation.","lore":null,"statut_regle":"correction","changements":"le trait Bande de ricanement disait « pour les Talents de Lignée » : les trois talents du livre (Harcèlement tournant, Rire de ralliement, La Bande rit encore) en sont l''usage. Harcèlement tournant ressemble à Chasse coordonnée (Garou, Pelage Noir) ; son ressort propre est déjà là : la Bande d''une scène, pas une Meute, et le déclencheur est la blessure infligée par n''importe quel membre. Exclusion surnaturelle redite, retirée de Mâchoire broyeuse."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'boudas_hommes_hyenes_talents_de_lignee_machoire_broyeuse_1_ptv_machoire_broyeuse', 'Mâchoire broyeuse', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"A","acces":"R","activation":null,"texte_court":"en animal ou hybride, ta morsure a Perforant 1 contre l''Armure matérielle (os, bois, plastique rigide, protections). Rien contre une Protection surnaturelle.","texte_reference":"R — Animal/Hybride La morsure peut attaquer efficacement os, bois, plastiques rigides et protections matérielles : elle possède Perforant 1 contre l’Armure matérielle uniquement. Aucun effet n’est ajouté contre Protection surnaturelle ou existence immatérielle.\nS’applique à l’Armure matérielle uniquement ; aucune pénétration de Protection surnaturelle ni interaction avec l’immatériel offerte.","lore":"La mâchoire des Boudas n’est pas seulement destinée à déchirer la chair. Os, bois et protections rigides peuvent céder sous une pression faite pour ouvrir les carcasses, puissance matérielle qui ne prétend pourtant rien contre une défense purement occulte.","statut_regle":"correction","changements":"le trait Bande de ricanement disait « pour les Talents de Lignée » : les trois talents du livre (Harcèlement tournant, Rire de ralliement, La Bande rit encore) en sont l''usage. Harcèlement tournant ressemble à Chasse coordonnée (Garou, Pelage Noir) ; son ressort propre est déjà là : la Bande d''une scène, pas une Meute, et le déclencheur est la blessure infligée par n''importe quel membre. Exclusion surnaturelle redite, retirée de Mâchoire broyeuse."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_boudas_harcelement_tournant', 'Harcèlement tournant', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"A","acces":"R, 1/round","activation":null,"texte_court":"quand un membre de ta Bande vient d''infliger au moins 1 PV à une cible, un autre membre reçoit Assistance +2 sur sa prochaine attaque contre elle avant la fin du round, malgré l''interdiction normale en combat. Une seule par attaque.","texte_reference":"quand un membre de ta Bande vient d''infliger au moins 1 PV à une cible, un autre membre reçoit Assistance +2 sur sa prochaine attaque contre elle avant la fin du round, malgré l''interdiction normale en combat. Une seule par attaque.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15). le trait Bande de ricanement disait « pour les Talents de Lignée » : les trois talents du livre (Harcèlement tournant, Rire de ralliement, La Bande rit encore) en sont l''usage. Harcèlement tournant ressemble à Chasse coordonnée (Garou, Pelage Noir) ; son ressort propre est déjà là : la Bande d''une scène, pas une Meute, et le déclencheur est la blessure infligée par n''importe quel membre. Exclusion surnaturelle redite, retirée de Mâchoire broyeuse."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'boudas_hommes_hyenes_talents_de_lignee_charognard_increvable_1_ptv_charognard_increvable', 'Charognard increvable', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"B","acces":"R","activation":null,"texte_court":"la charogne ne te rend pas malade ; +3 pour résister aux poisons et toxines non surnaturels ingérés.","texte_reference":"Conservez l’immunité aux troubles alimentaires ordinaires de la charogne et gagnez +3 pour résister aux poisons ou toxines non surnaturels ingérés. Cela ne donne aucune immunité aux poisons préparés, aux maladies surnaturelles ou aux contaminations de Fléau.\nLe bonus est limité à l’ingestion : pas aux gaz, injections ou venins de morsure. Les exclusions de Fléau restent intactes.","lore":"Le système digestif du Bouda traite la putréfaction comme un environnement attendu plutôt qu’une catastrophe. Viandes tournées et agents alimentaires ordinaires rencontrent une physiologie de charognard, sans offrir la moindre protection particulière contre un poison conçu ou une contamination surnaturelle.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_boudas_rire_de_ralliement', 'Rire de ralliement', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"B","acces":"SR/R, 1 PA","activation":null,"texte_court":"par un rire bref, tous les membres de ta Bande qui t''entendent comprennent une impulsion simple : danger, repli, proie, rassemblement ou changement de cible. Ni langage commun ni télépathie.","texte_reference":"par un rire bref, tous les membres de ta Bande qui t''entendent comprennent une impulsion simple : danger, repli, proie, rassemblement ou changement de cible. Ni langage commun ni télépathie.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15). le trait Bande de ricanement disait « pour les Talents de Lignée » : les trois talents du livre (Harcèlement tournant, Rire de ralliement, La Bande rit encore) en sont l''usage. Harcèlement tournant ressemble à Chasse coordonnée (Garou, Pelage Noir) ; son ressort propre est déjà là : la Bande d''une scène, pas une Meute, et le déclencheur est la blessure infligée par n''importe quel membre. Exclusion surnaturelle redite, retirée de Mâchoire broyeuse."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_boudas_la_bande_rit_encore', 'La Bande rit encore', NULL, '{"nature":"khinae","cout":3,"cout_actuel":0,"palier":"III","porte":"sommet","acces":"R, Réaction, 1 PA, 1/scène","activation":null,"texte_court":"quand un membre de ta Bande devient Agonisant ou est immobilisé par une menace perçue, un autre membre se déplace aussitôt vers lui ou attaque normalement la source, avec son propre PA de Réaction.","texte_reference":"quand un membre de ta Bande devient Agonisant ou est immobilisé par une menace perçue, un autre membre se déplace aussitôt vers lui ou attaque normalement la source, avec son propre PA de Réaction.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15). le trait Bande de ricanement disait « pour les Talents de Lignée » : les trois talents du livre (Harcèlement tournant, Rire de ralliement, La Bande rit encore) en sont l''usage. Harcèlement tournant ressemble à Chasse coordonnée (Garou, Pelage Noir) ; son ressort propre est déjà là : la Bande d''une scène, pas une Meute, et le déclencheur est la blessure infligée par n''importe quel membre. Exclusion surnaturelle redite, retirée de Mâchoire broyeuse."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'khinae', 'khinae_berserkirs', 'Berserkirs', NULL, '{"nature":"khinae","forme":"deux_portes_sommet","verrou":"ordre_paliers","lignee":"berserkirs","portes":{"A":"L''étreinte","B":"Le vieil ours"},"profil":"- **Animal** : +3 Vigueur · griffes et morsure DGT 5 · Armure 2 · déplacement puissant, non accéléré.\n- **Hybride** : +5 Vigueur, +0 Agilité · DGT 6 · Armure 3.\n- **Variantes** : *Brun / Grizzly* (référence) · *Polaire* (froid extrême, nage, immersion glaciale) · *Ours noir* (+4 Vigueur / +1 Agilité, DGT 6, Armure 2 ; meilleur grimpeur).","impulsion":"la menace contre un protégé","description":"Les Berserkirs sont des Hommes-Ours massifs issus d’anciennes lignées autrefois proches des Ulfhednars. Leur héritage privilégie masse, endurance et puissance immédiate ; la forme animale choisie nuance ensuite froid, nage, grimpe ou gabarit.","changements":"préfixe d''accès retiré de Torpeur profonde. Quand l''Ours se lève donne un déclencheur de Frénésie à la Lignée (le rapport notait une Frénésie « sans objet » chez les Khinae)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_berserkirs_masse_ursine', 'Masse ursine', NULL, '{"nature":"khinae","cout":0,"cout_actuel":0,"palier":"signature","porte":null,"acces":"R, hybride","activation":null,"texte_court":"une force humaine ordinaire ne peut pas te renverser, te pousser ni te soulever. Un adversaire surnaturel, un véhicule, une explosion ou la rupture du sol le peuvent.","texte_reference":"une force humaine ordinaire ne peut pas te renverser, te pousser ni te soulever. Un adversaire surnaturel, un véhicule, une explosion ou la rupture du sol le peuvent.","lore":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'berserkirs_hommes_ours_talents_de_lignee_etreinte_dours_1_ptv_etreinte_dours', 'Étreinte d''ours', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"A","acces":"R","activation":null,"texte_court":"après une saisie réussie en animal ou hybride, +3 pour tenir la prise, et tu peux emporter à demi-Déplacement une cible que ta force permet de porter.","texte_reference":"Après une saisie réussie en Animal ou Hybride, gagnez +3 pour maintenir la prise et vous pouvez déplacer à demi-Déplacement une cible que votre force permet de porter. Aucun dégât, étouffement ou second adversaire saisi n’est ajouté automatiquement.\nLe déplacement se paie normalement ; le bonus de maintien ne transforme pas la saisie initiale en réussite automatique.","lore":"Une fois les bras du Berserkir refermés, le contact devient une prison de masse et de leviers. La proie n’en sort pas simplement en reculant : elle doit vaincre la force qui la tient ou trouver un moyen véritable de briser l’étreinte.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_berserkirs_pas_de_recul', 'Pas de recul', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"A","acces":"R, hybride","activation":null,"texte_court":"quand tu avances droit vers une menace, une Impulsion de Frénésie ou quelqu''un que tu protèges, une créature de gabarit comparable doit gagner une opposition de Vigueur pour seulement te barrer le passage. Ni mur ni obstacle infranchissable.","texte_reference":"quand tu avances droit vers une menace, une Impulsion de Frénésie ou quelqu''un que tu protèges, une créature de gabarit comparable doit gagner une opposition de Vigueur pour seulement te barrer le passage. Ni mur ni obstacle infranchissable.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'berserkirs_hommes_ours_talents_de_lignee_torpeur_profonde_1_ptv_torpeur_profonde', 'Torpeur profonde', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"B","acces":"R","activation":null,"texte_court":"hors combat, en quelques minutes, tu entres en torpeur volontaire. Tes besoins chutent ; dans un lieu sûr, tu tiens des jours ou des semaines. Réveil en quelques instants.","texte_reference":"R — hors combat En quelques minutes, le Berserkir peut entrer dans une torpeur volontaire. Ses besoins ordinaires en nourriture, eau et activité chutent drastiquement ; dans un lieu sûr il peut demeurer ainsi des jours ou semaines. Se réveiller volontairement demande quelques instants, pas une scène entière.\nPréserver les jours ou semaines de réduction des besoins dans un abri sûr et un réveil rapide. Ni régénération de combat gratuite en torpeur, ni défense d’un personnage inconscient, ni résistance universelle au milieu.","lore":"Le Berserkir sait ralentir volontairement son immense organisme jusqu’à une torpeur proche de l’hibernation. Dans un refuge sûr, faim, soif et besoin d’activité reculent pendant des jours, laissant le corps attendre sans réellement s’abandonner au sommeil ordinaire.","statut_regle":"correction","changements":"préfixe d''accès retiré de Torpeur profonde. Quand l''Ours se lève donne un déclencheur de Frénésie à la Lignée (le rapport notait une Frénésie « sans objet » chez les Khinae)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_berserkirs_ancien_pacte_ulfhednar', 'Ancien pacte Ulfhednar', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"B","acces":"R, spécial","activation":null,"texte_court":"une fois le vieux pacte rétabli dans la fiction avec un membre reconnu des Pelages Blancs, vous pouvez vous accorder mutuellement Assistance +2 sur une Compétence de combat, malgré l''interdiction normale. Le talent ne recrée pas le pacte.","texte_reference":"une fois le vieux pacte rétabli dans la fiction avec un membre reconnu des Pelages Blancs, vous pouvez vous accorder mutuellement Assistance +2 sur une Compétence de combat, malgré l''interdiction normale. Le talent ne recrée pas le pacte.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_berserkirs_quand_l_ours_se_leve', 'Quand l''Ours se lève', NULL, '{"nature":"khinae","cout":3,"cout_actuel":0,"palier":"III","porte":"sommet","acces":"R, Réaction, 1 PA, 1/scène","activation":null,"texte_court":"la première fois que tu passes sous la moitié de tes PV, ou qu''un proche à portée subit une attaque qui pourrait l''abattre, tu entres en Frénésie avec cette menace pour Impulsion et te portes vers elle ou vers le protégé. Ni DGT ni attaque gratuits.","texte_reference":"la première fois que tu passes sous la moitié de tes PV, ou qu''un proche à portée subit une attaque qui pourrait l''abattre, tu entres en Frénésie avec cette menace pour Impulsion et te portes vers elle ou vers le protégé. Ni DGT ni attaque gratuits.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15). préfixe d''accès retiré de Torpeur profonde. Quand l''Ours se lève donne un déclencheur de Frénésie à la Lignée (le rapport notait une Frénésie « sans objet » chez les Khinae)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'khinae', 'khinae_crocodiliens', 'Crocodiliens', NULL, '{"nature":"khinae","forme":"deux_portes_sommet","verrou":"ordre_paliers","lignee":"crocodiliens","portes":{"A":"La mâchoire","B":"L''eau"},"profil":"- **Animal** : +3 Vigueur · morsure DGT 5 · Armure 3 · excellente nage · lent et encombré à terre.\n- **Hybride** : +5 Vigueur ; Agilité +0 à terre, +2 dans l''eau · morsure DGT 6 · Armure 3 *(Armure 4 → 3, B2 validé)*.\n- **Variantes** : *Nil / marin* (référence, eau libre) · *Alligator* (+4 Vigueur / +1 Agilité à terre, +2 Agilité dans l''eau, Armure 3) · *Caïman* (+4 / +1, DGT 5, Armure 3 ; zones encombrées) · *Gavial* (+3 Vigueur / +2 Agilité dans l''eau, DGT 5, Armure 2 ; capture aquatique rapide).","impulsion":"la proie au bord de l''eau","description":"Les Crocodiliens sont une branche lourde de Khinae spécialisée dans l’embuscade aquatique et la patience prédatrice. Armure naturelle, puissance de saisie et adaptation au milieu dominent leur Nature, avec des variantes allant du grand crocodile au caïman plus compact.","changements":"aucun sur les talents existants. Les trois saisies (Saisie du fauve, Étreinte d''ours, Mâchoire verrouillée) restent séparées : chacune appartient à une Lignée différente, et un personnage n''a qu''une Lignée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_crocodiliens_fossile_de_vase', 'Fossile de vase', NULL, '{"nature":"khinae","cout":0,"cout_actuel":0,"palier":"signature","porte":null,"acces":"R, animal ou hybride","activation":null,"texte_court":"tu restes presque parfaitement immobile toute une scène. Une détection fondée sur le seul mouvement ou l''agitation de l''eau échoue ; chaleur, odorat, contact et capteurs adaptés fonctionnent.","texte_reference":"tu restes presque parfaitement immobile toute une scène. Une détection fondée sur le seul mouvement ou l''agitation de l''eau échoue ; chaleur, odorat, contact et capteurs adaptés fonctionnent.","lore":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'crocodiliens_les_fossiles_dembuscade_talents_de_lignee_machoire_verrouillee_1_ptv_machoire_verrouillee', 'Mâchoire verrouillée', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"A","acces":"R","activation":null,"texte_court":"1/round, une morsure payée qui inflige au moins 1 PV verrouille la prise, sans PA ni jet de plus. La cible se libère par l''opposition physique normale.","texte_reference":"Une fois par round, une morsure payée qui inflige au moins 1 PV réel peut verrouiller la prise sans PA ni second jet supplémentaires. La cible doit se libérer par l’opposition physique normale ou un moyen approprié ; la morsure n’est pas infligée une seconde fois.\nLa prise utilise la mâchoire et les contraintes de taille demeurent. Traîner ou noyer exige ses actions et conditions normales, sans effet instantané ajouté.","lore":"Après la morsure, les mâchoires ne servent plus à frapper mais à tenir. La prise se verrouille autour de la proie et transforme tout déplacement en lutte contre l’anatomie même du Crocodilien.","statut_regle":"correction","changements":"aucun sur les talents existants. Les trois saisies (Saisie du fauve, Étreinte d''ours, Mâchoire verrouillée) restent séparées : chacune appartient à une Lignée différente, et un personnage n''a qu''une Lignée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_crocodiliens_roulade_de_mort', 'Roulade de mort', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"A","acces":"R, 1 PA","activation":null,"texte_court":"sur une cible verrouillée, Vigueur + Pugilat contre sa défense physique. En réussite, une nouvelle attaque naturelle DGT 6 (ou celui de ta Variante), et tu peux la renverser si le gabarit le permet. C''est une attaque payée.","texte_reference":"sur une cible verrouillée, Vigueur + Pugilat contre sa défense physique. En réussite, une nouvelle attaque naturelle DGT 6 (ou celui de ta Variante), et tu peux la renverser si le gabarit le permet. C''est une attaque payée.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'crocodiliens_les_fossiles_dembuscade_talents_de_lignee_apnee_seculaire_1_ptv_apnee_seculaire', 'Apnée séculaire', NULL, '{"nature":"khinae","cout":1,"cout_actuel":1,"palier":"I","porte":"B","acces":"R","activation":null,"texte_court":"en animal ou hybride, une heure sous l''eau sans effort soutenu, ou toute une scène de combat sans manquer d''air.","texte_reference":"En Animal ou Hybride, restez submergé une heure sans effort soutenu, ou toute une scène de combat sans manquer d’air. Ce n’est ni une respiration aquatique permanente ni une protection contre le vide, la pression ou un autre milieu mortel.\nPas de jauge remise à plein au rechargement ou au passage d’une forme à l’autre ; une vraie reprise de souffle demeure nécessaire.","lore":"Le Crocodilien peut laisser son souffle disparaître de la scène pendant un temps démesuré. Sous l’eau, son métabolisme accepte l’immobilité et l’attente avec une patience fossile, ne réclamant de l’air rapidement que lorsque l’effort devient réellement violent.","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_crocodiliens_embuscade_de_berge', 'Embuscade de berge', NULL, '{"nature":"khinae","cout":2,"cout_actuel":0,"palier":"II","porte":"B","acces":"R, 1/scène","activation":null,"texte_court":"si tu commences non localisé dans l''eau, la vase ou un couvert semblable, et qu''une cible est à portée de Déplacement, tu émerges jusqu''au contact sans être trahi par le seul mouvement de l''eau.","texte_reference":"si tu commences non localisé dans l''eau, la vase ou un couvert semblable, et qu''une cible est à portée de Déplacement, tu émerges jusqu''au contact sans être trahi par le seul mouvement de l''eau.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'khinae', 'khinae_crocodiliens_emporter_sous_l_eau', 'Emporter sous l''eau', NULL, '{"nature":"khinae","cout":3,"cout_actuel":0,"palier":"III","porte":"sommet","acces":"R, 1 PA, 1/scène","activation":null,"texte_court":"sur une cible verrouillée, si une masse d''eau suffisante est à portée de Déplacement, opposition de Vigueur : en réussite, tu l''entraînes dans l''eau et elle n''en sort pas par un simple Déplacement tant que la prise tient. Aucune asphyxie instantanée.","texte_reference":"sur une cible verrouillée, si une masse d''eau suffisante est à portée de Déplacement, opposition de Vigueur : en réussite, tu l''entraînes dans l''eau et elle n''en sort pas par un simple Déplacement tant que la prise tient. Aucune asphyxie instantanée.","lore":null,"statut_regle":"correction","changements":"Rétabli du livre V6 (chapitre 12), absent du site (lot 02, lot 15)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
